using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;
using VerifyCS = CSharpSourceGeneratorVerifier<MessagePack.SourceGenerator.MessagePackGenerator>;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageReceiptTests
{
    private const string ResolverSourceWithExistingAttribute = """
        using MessagePack;

        [MessagePackObject]
        public class MyObject
        {
            [Key(0)]
            public int A { get; set; }
        }

        [global::System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverage]
        [GeneratedMessagePackResolver]
        partial class MyResolver
        {
        }
        """;

    private const string ResolverSource = """
        using MessagePack;

        [MessagePackObject]
        public class MyObject
        {
            [Key(0)]
            public int A { get; set; }
        }

        [GeneratedMessagePackResolver]
        partial class MyResolver
        {
        }
        """;

    [Fact]
    public async Task UserResolverAlreadyExcludedFromCoverage_CompilesWithoutDuplicateAttribute()
    {
        var test = new VerifyCS.Test()
        {
            TestBehaviors = TestBehaviors.SkipGeneratedSourcesCheck,
        };
        test.TestState.Sources.Add(ResolverSourceWithExistingAttribute);
        await test.RunAsync();
    }

    [Fact]
    public async Task ResolverExcludedFromCoverage_WhenCompilingForNetStandard20()
    {
        ImmutableArray<MetadataReference> frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        IEnumerable<MetadataReference> allRefs = frameworkRefs.Concat<MetadataReference>(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToList();

        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.CSharp7_3, preprocessorSymbols: new[] { "NETSTANDARD2_0" });
        SyntaxTree tree = CSharpSyntaxTree.ParseText(ResolverSource, parseOptions);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsTestAssembly",
            new[] { tree },
            allRefs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> generatorDiagnostics);

        Assert.Empty(generatorDiagnostics.Where(d => d.Severity == DiagnosticSeverity.Error));
        Assert.True(driver.GetRunResult().GeneratedTrees.Length > 0, "Generator produced no sources.");

        INamedTypeSymbol? resolver = output.GetTypeByMetadataName("MyResolver");
        Assert.NotNull(resolver);
        bool excluded = resolver!.GetAttributes().Any(a => a.AttributeClass?.Name == "ExcludeFromCodeCoverageAttribute");
        Assert.True(excluded, "Generated resolver is not decorated with ExcludeFromCodeCoverage when NETSTANDARD2_0 is defined, although the attribute exists on netstandard2.0.");
    }
}
